package org.intelehealth.ezazi.stage3.dbimport android.util.Logimport org.intelehealth.ezazi.database.dao.VisitAttributeListDAOimport org.intelehealth.ezazi.models.dto.EncounterDTOimport org.intelehealth.ezazi.stage3.models.DeliveryDetailsimport org.intelehealth.ezazi.syncModule.SyncUtilsimport org.intelehealth.ezazi.utilities.UuidDictionaryclass DeliveryDetailsRepository(    private val localDataSource: DeliveryDetailsLocalDataSource,    private val mapper: DeliveryDetailsObsMapper,    private val syncUtils: SyncUtils) {    private val TAG = "DeliveryRepository"    fun saveDeliveryDetails(encounterDTO: EncounterDTO, deliveryDetails: DeliveryDetails, creatorUuid: String, encounterTypeName: String, visitAttributeListDAO : VisitAttributeListDAO): Boolean {        //  insert encounter- Women delivery outcome        val isEncounterInserted = localDataSource.insertEncounter(encounterDTO)        if (!isEncounterInserted) {            return false        }        val obsList = mapper.mapToObsList(encounterDTO.uuid, deliveryDetails, creatorUuid)        // Insert obs        val isObsInserted = localDataSource.saveDeliveryObsData(obsList)        if (!isObsInserted) return false        val resultFirstEncStage3 =localDataSource.createStage3FirstEncounter(encounterDTO.visituuid, encounterTypeName)        // If data inserted        localDataSource.updateDecisionPendingFlagAndUnSyncVisitFlag(encounterDTO.visituuid, "false")        if (!resultFirstEncStage3) {            return false        }        //  Call only if Stage3 encounter created successfully        val updated = visitAttributeListDAO.upsertVisitAttribute(encounterDTO.visituuid, UuidDictionary.VISIT_RISK, "0")        //syncUtils.syncForeground("visitSummary")        return true    }}